const int thinfont_numglyphs = sizeof(thinfont_glyphs) / sizeof(thinfont_glyphs[0]);

// Tries the exact character first (so a real lowercase glyph like 't'/'i'/'s'
// gets used when one exists), then falls back to its uppercase fold. That
// fallback is what makes every other letter work unchanged: most of this
// table's "lowercase-looking" glyphs (o, n, e, r, g, l, y, p) are actually
// stored under their uppercase ASCII code (see the file header comment), so
// a lowercase 'o' in some caller's string still needs to reach the entry
// keyed 'O' to find them.
//
// A last fallback goes the other way, uppercase down to lowercase: a few
// letters (a, m, ...) only exist as genuine lowercase glyphs with no
// separate capital cropped anywhere (see the header comment and
// tools/gen_thinfont.py - no supported IWAD's menu patches contain a
// cleanly isolated capital of these), so a word like "All Weapons" would
// otherwise render with a blank gap where the capital should be instead of
// a slightly-short-looking but legible letter.
static const thinglyph_t *find_glyph(int ch)
{
    int i;
    int upper, lower;

    for (i = 0; i < thinfont_numglyphs; i++)
    {
        if (thinfont_glyphs[i].ch == ch)
        {
            return &thinfont_glyphs[i];
        }
    }

    upper = toupper(ch);
    if (upper != ch)
    {
        for (i = 0; i < thinfont_numglyphs; i++)
        {
            if (thinfont_glyphs[i].ch == upper)
            {
                return &thinfont_glyphs[i];
            }
        }
    }

    lower = tolower(ch);
    if (lower != ch)
    {
        for (i = 0; i < thinfont_numglyphs; i++)
        {
            if (thinfont_glyphs[i].ch == lower)
            {
                return &thinfont_glyphs[i];
            }
        }
    }

    return NULL;
}

int M_ThinStringWidth(char *string)
{
    char *p;
    int w = 0;
    const thinglyph_t *g;

    for (p = string; *p; p++)
    {
        g = find_glyph((unsigned char)*p);
        w += (g ? g->width : TF_BLANK_WIDTH) + TF_SPACING;
    }

    return w;
}

void M_WriteThinText(int x, int y, char *string)
{
    char *p;
    int cx, cy;
    int row, col;
    uint8_t pixel;
    byte *dest;
    const thinglyph_t *g;

    cx = x;
    cy = y;

    for (p = string; *p; p++)
    {
        if (*p == '\n')
        {
            cx = x;
            cy += TF_HEIGHT + 2;
            continue;
        }

        g = find_glyph((unsigned char)*p);

        if (!g)
        {
            cx += TF_BLANK_WIDTH + TF_SPACING;
            continue;
        }

        for (row = 0; row < TF_HEIGHT; row++)
        {
            dest = (byte*)bufptr + (cy+row)*SCREENWIDTH + cx;

            for (col = 0; col < g->width; col++)
            {
                pixel = g->pixels[row][col];

                if (pixel)
                {
                    dest[col] = pixel;
                }
            }
        }

        cx += g->width + TF_SPACING;
    }
}
